local ParseUtils = CS.ParseUtils

local function ParseIdAndNumList(row, idKay, numKey)
    local list = {}
    local str_add = parse_string(row, idKay)
    if not (string.isEmpty(str_add) or str_add == '0') then
        local ids    = parse_strings(str_add)
        local numArr = parse_strings(parse_string(row, numKey))
        local length = math.min(#ids, #numArr)
        for i = 1, length do
            table.insert(list, {
                id   = ids[i],
                num = checkNumber(numArr[i])
            })
        end
    end
    return list
end

