end


---FillVo
---@param row TableML.TableFileRow
function TalentVo:FillVo(row)
    base.FillVo(self,row)
    self.name = ParseUtils.ParseLocalizeText(row, "name");
    self.desc = ParseUtils.ParseLocalizeText(row, "desc");

    self.iconPath = ParseUtils.ParsePathName(row, "icon")

    self.talentType = parse_number(row, "type")

    self.passive       = ParseIdAndNumList(row, "addSkillId", "star")
    self.exPassive     = ParseIdAndNumList(row, "exSkillId", "exStar")
    
    local attrs = {}
    if self.talentType == Constants.TalentType.Strength then
        local str_add = parse_string(row, "attAddTypeId")
        if not (string.isEmpty(str_add) or str_add == '0') then
            local ids = parse_strings(str_add)
            local nums = parse_strings(parse_string(row, "attAddNum"))
            local length = math.min(#ids, #nums)
            for i = 1, length do
                -- table.insert(attrs, {
                --     id = ids[i],
                --     addV = checkNumber(nums[i])
                -- })
                attrs[ids[i]] = checkNumber(nums[i])
            end
        end
    end
    self.attrAdditions = attrs

    self.effShowList = base.GetFieldList(self, row, "effShow")

    self.descOther = parse_string(row, "descOther")
end

